#include <iostream>
#include <iomanip>
#include <vector>
#include <string_view>
// Generated by Verilator from pipeline_top.sv
#include "Vpipeline_top.h" 
#include "verilated.h"

// Reusable function to inject a packet and monitor the outputs
void inject_packet(Vpipeline_top* dut, const std::vector<uint8_t>& packet, std::string_view name) {
    std::cout << "\nInjecting " << name << "...\n";
    
    for (std::size_t i = 0; i < packet.size(); ++i) {
        // Drive data and valid
        dut->s_axis_tdata = packet[i];
        dut->s_axis_tvalid = 1;
        dut->s_axis_tlast = (i == packet.size() - 1) ? 1 : 0;
        
        // Toggle clock
        dut->clk = 1; dut->eval();
        dut->clk = 0; dut->eval();

        // Check if the classifier has evaluated this packet
        if (dut->classify_valid) {
            std::cout << "Classification Result -> action_drop: " 
                      << static_cast<int>(dut->action_drop) << "\n";
        }
    }
    
    // Add a few idle clock cycles between packets
    dut->s_axis_tvalid = 0;
    for (int i = 0; i < 5; ++i) {
        dut->clk = 1; dut->eval();
        dut->clk = 0; dut->eval();
    }
}

int main(int argc, char** argv) {
    Verilated::commandArgs(argc, argv);
    
    // Instantiate the NEW top-level module
    Vpipeline_top* dut = new Vpipeline_top;

    // Initialize inputs
    dut->clk = 0;
    dut->rst_n = 0; 
    dut->s_axis_tvalid = 0;
    dut->s_axis_tdata = 0;
    dut->s_axis_tlast = 0;

    // Reset sequence
    dut->clk = 1; dut->eval();
    dut->clk = 0; dut->eval();
    dut->rst_n = 1;
    dut->clk = 1; dut->eval();
    dut->clk = 0; dut->eval();

    // Benign Packet (Source IP: 192.168.1.50 -> C0 A8 01 32)
    std::vector<uint8_t> benign_packet = {
        0xAA, 0xAA, 0xAA, 0xAA, 0xAA, 0xAA, 0xBB, 0xBB, 0xBB, 0xBB, 0xBB, 0xBB,
        0x08, 0x00, 0x45, 0x00, 0x00, 0x2E, 0x00, 0x00, 0x00, 0x00, 0x40, 0x11, 
        0x00, 0x00, 
        0xC0, 0xA8, 0x01, 0x32, // Source IP: 192.168.1.50
        0x0A, 0x00, 0x00, 0x01, 0x04, 0xD2, 0x00, 0x50, 0x00, 0x00, 0x00, 0x00
    };

    // Malicious Packet (Source IP: 192.168.1.100 -> C0 A8 01 64)
    std::vector<uint8_t> malicious_packet = benign_packet;
    malicious_packet[29] = 0x64; // Overwrite the last byte of the Source IP to 100

    // Run the simulation
    inject_packet(dut, benign_packet, "Benign Packet (192.168.1.50)");
    inject_packet(dut, malicious_packet, "Malicious Packet (192.168.1.100)");

    // Cleanup
    delete dut;
    return 0;
}